// Contract models for the Dry Run API. Pure Dart, no Flutter imports.
//
// Every model is a freezed value type generated by json_serializable. The
// constructor annotations use `disallowUnrecognizedKeys` so a contract fixture
// with an unexpected field fails to parse instead of being silently ignored.

import 'package:freezed_annotation/freezed_annotation.dart';

part 'models.freezed.dart';
part 'models.g.dart';

enum AppLanguage {
  @JsonValue('en')
  en,
  @JsonValue('hi')
  hi,
  @JsonValue('hinglish')
  hinglish,
}

enum SessionMode {
  @JsonValue('chat')
  chat,
  @JsonValue('voice')
  voice,
}

enum StageId {
  @JsonValue('contact')
  contact,
  @JsonValue('accusation')
  accusation,
  @JsonValue('isolation')
  isolation,
  @JsonValue('urgency')
  urgency,
  @JsonValue('transfer')
  transfer,
}

enum LabelId {
  @JsonValue('P1')
  p1,
  @JsonValue('P2')
  p2,
  @JsonValue('P3')
  p3,
  @JsonValue('P4')
  p4,
  @JsonValue('C1')
  c1,
  @JsonValue('C2')
  c2,
  @JsonValue('C3')
  c3,
  @JsonValue('C4')
  c4,
}

enum TurnStatus {
  @JsonValue('active')
  active,
  @JsonValue('ended')
  ended,
}

enum EndReason {
  @JsonValue('hung_up')
  hungUp,
  @JsonValue('verified_callback')
  verifiedCallback,
  @JsonValue('complied_transfer')
  compliedTransfer,
  @JsonValue('turn_cap')
  turnCap,
  @JsonValue('timeout')
  timeout,
  @JsonValue('participant_ended')
  participantEnded,
}

enum HabitId {
  @JsonValue('hang_up')
  hangUp,
  @JsonValue('call_back_official')
  callBackOfficial,
  @JsonValue('tell_family')
  tellFamily,
}

enum DebriefQuality {
  @JsonValue('quick')
  quick,
  @JsonValue('full')
  full,
}

enum DebriefStatus {
  @JsonValue('pending')
  pending,
  @JsonValue('ready')
  ready,
}

enum ProblemCode {
  @JsonValue('invalid_token')
  invalidToken,
  @JsonValue('token_expired')
  tokenExpired,
  @JsonValue('session_limit_reached')
  sessionLimitReached,
  @JsonValue('turn_index_mismatch')
  turnIndexMismatch,
  @JsonValue('rate_limited')
  rateLimited,
  @JsonValue('payload_too_large')
  payloadTooLarge,
  @JsonValue('consent_required')
  consentRequired,
  @JsonValue('session_ended')
  sessionEnded,
  @JsonValue('validation_error')
  validationError,
  @JsonValue('internal')
  internal,
}

enum EndedStatus {
  @JsonValue('ended')
  ended,
}

@freezed
class ProblemDetail with _$ProblemDetail {
  @JsonSerializable(
    disallowUnrecognizedKeys: true,
    explicitToJson: true,
    fieldRename: FieldRename.snake,
  )
  const factory ProblemDetail({
    required String type,
    required String title,
    required int status,
    required String detail,
    required ProblemCode code,
  }) = _ProblemDetail;

  factory ProblemDetail.fromJson(Map<String, dynamic> json) =>
      _$ProblemDetailFromJson(json);
}

