@freezed
class TurnResponse with _$TurnResponse {
  @JsonSerializable(
    disallowUnrecognizedKeys: true,
    explicitToJson: true,
    fieldRename: FieldRename.snake,
  )
  @Assert('pressure >= 0 && pressure <= 3', 'pressure must be between 0 and 3')
  @Assert('turnIndex >= 0', 'turn index must not be negative')
  const factory TurnResponse({
    OfficerLine? officerLine,
    required StageId stageId,
    required int pressure,
    required TurnStatus status,
    EndReason? endReason,
    required int turnIndex,
    required bool fallbackUsed,
    required bool piiWarning,
  }) = _TurnResponse;

  factory TurnResponse.fromJson(Map<String, dynamic> json) =>
      _$TurnResponseFromJson(json);
}

